8347560913ed0e','source_text_sha256':'a83ce63650704d287460cb3a62accc56bc50d071ba04f35c5179207de564ada8','source_pages':[68]],['clause_id':'FSAE-2027-V1:T.4.3.2:p003','source_rule_id':'T.4.3.2','source_sha256':'f71df5552e341dab1b58f1ff47212e7281953d66b9c41833de8347560913ed0e','source_text_sha256':'80fe88c8aeb2dbb5873e637f4a44336270bc78cac3fb9664b077437baa636bc6','source_pages':[68]]],'classification':'design_and_inspection_process','interpretation_status':'interpreted_candidate','coverage_status':'prepared_not_applied','verification_method':'inspection_review_and_fault_injection','verification_status':'not_verified','evidence_status':'not_available','compliance_status':'not_claimed','conditions_json':'["All BSE signal connections used by the chosen implementation."]','numeric_json':'[]','source_ids_json':'["FSAE-2027-V1:T.4.3.2:p001","FSAE-2027-V1:T.4.3.2:p002","FSAE-2027-V1:T.4.3.2:p003"]'],['id':'DD-10','title':'Latch simultaneous brake and accelerator conflict','rules':['EV.4.7.1','EV.4.7.2'],'functions':['brake-conflict','motor-inhibit','inspection'],'owner':'driver-demand brake/APPS latch / powertrain','statement':'Monitor mechanical-brake engagement together with APPS travel greater than twenty-five percent. When both occur, immediately and completely remove motor power. Keep that inhibit active until APPS travel is below five percent, regardless of brake operation. Demonstrate the complete behavior at technical inspection.','conditions':['Mechanical brakes engaged, not simply any nonzero pedal travel; EV.4.6/T.3.2.4 are retained as source dependencies.'],'numeric':[['quantity':'conflict APPS threshold','value':25,'unit':'% pedal travel','operator':'>'],['quantity':'inhibit release APPS threshold','value':5,'unit':'% pedal travel','operator':'<']],'checks':'Exercise mechanical-brake engagement with APPS below, at and above twenty-five percent. Demonstrate complete motor-power removal and persistence despite brake release until APPS is strictly below five percent; check the five-percent boundary.','source_refs':[['clause_id':'FSAE-2027-V1:EV.4.7.1:p001','source_rule_id':'EV.4.7.1','source_sha256':'f71df5552e341dab1b58f1ff47212e7281953d66b9c41833de8347560913ed0e','source_text_sha256':'2d6f3d8ce2308f7aa0daaf10617d1704bf4b9923a350838928d85023a05846ac','source_pages':[95]],['clause_id':'FSAE-2027-V1:EV.4.7.1:p002','source_rule_id':'EV.4.7.1','source_sha256':'f71df5552e341dab1b58f1ff47212e7281953d66b9c41833de8347560913ed0e','source_text_sha256':'62c9566eb31b16fd4907caa77b1fecf1027950f2aa74abe1f45954721ac3d02e','source_pages':[95]],['clause_id':'FSAE-2027-V1:EV.4.7.1:p003','source_rule_id':'EV.4.7.1','source_sha256':'f71df5552e341dab1b58f1ff47212e7281953d66b9c41833de8347560913ed0e','source_text_sha256':'81d6f29d062000bdb5b6fcb6b44790e9eacbaa8b2f7be579247c74d54bb7a31d','source_pages':[95]],['clause_id':'FSAE-2027-V1:EV.4.7.2:p001','source_rule_id':'EV.4.7.2','source_sha256':'f71df5552e341dab1b58f1ff47212e7281953d66b9c41833de8347560913ed0e','source_text_sha256':'03054cb925abee94e20a031d4f5dec98dbc3187326675f32a46dbaaf8fe2d649','source_pages':[95]],['clause_id':'FSAE-2027-V1:EV.4.7.2:p002','source_rule_id':'EV.4.7.2','source_sha256':'f71df5552e341dab1b58f1ff47212e7281953d66b9c41833de8347560913ed0e','source_text_sha256':'87c478f59ecf39b5c77747b5451223f811503f1ed1011610ca43f7f1ab4e6ad1','source_pages':[95]],['clause_id':'FSAE-2027-V1:EV.4.7.2:p003','source_rule_id':'EV.4.7.2','source_sha256':'f71df5552e341dab1b58f1ff47212e7281953d66b9c41833de8347560913ed0e','source_text_sha256':'32ef75e369aff5c9ac2bc37a8065ad8452103b94dde3cffb7b35fb2cdd786747','source_pages':[95]],['clause_id':'FSAE-2027-V1:EV.4.7.2:p004','source_rule_id':'EV.4.7.2','source_sha256':'f71df5552e341dab1b58f1ff47212e7281953d66b9c41833de8347560913ed0e','source_text_sha256':'885b83395162d70c841b95138e7b724466dde04be32b3a5147a5d6ea90f4d5d2','source_pages':[95]]],'classification':'technical_design_and_verification','interpretation_status':'interpreted_candidate','coverage_status':'prepared_not_applied','verification_method':'inspection_review_and_fault_injection','verification_status':'not_verified','evidence_status':'not_available','compliance_status':'not_claimed','conditions_json':'["Mechanical brakes engaged, not simply any nonzero pedal travel; EV.4.6/T.3.2.4 are retained as source dependencies."]','numeric_json':'[{"quantity":"conflict APPS threshold","value":25,"unit":"% pedal travel","operator":">"},{"quantity":"inhibit release APPS threshold","value":5,"unit":"% pedal travel","operator":"<"}]','source_ids_json':'["FSAE-2027-V1:EV.4.7.1:p001","FSAE-2027-V1:EV.4.7.1:p002","FSAE-2027-V1:EV.4.7.1:p003","FSAE-2027-V1:EV.4.7.2:p001","FSAE-2027-V1:EV.4.7.2:p002","FSAE-2027-V1:EV.4.7.2:p003","FSAE-2027-V1:EV.4.7.2:p004"]'],['id':'DD-11','title':'BSPD independence from programmable pedal plausibility','rules':['EV.8.7.1'],'functions':['bspd-monitor','bspd-trip'],'owner':'shutdown independent BSPD','statement':'Provide a standalone nonprogrammable circuit that detects simultaneous braking and high motor-power output, independently of the APPS/brake pedal plausibility function. This candidate gives the BSPD a separate physical circuit and separately modeled sensor-input checks; it does not replace it with ECU firmware.','conditions':['Independent BSPD architecture and independence evidence still require design review.'],'numeric':[],'checks':'Review schematic, signal dependencies, power/fault paths and component implementation. Demonstrate that programmable APPS/BSE plausibility logic is not the BSPD implementation and cannot defeat its shutdown request.','source_refs':[['clause_id':'FSAE-2027-V1:EV.8.7.1:p001','source_rule_id':'EV.8.7.1','source_sha256':'f71df5552e341dab1b58f1ff47212e7281953d66b9c41833de8347560913ed0e','source_text_sha256':'75651ba5b9f819011c274ee20447ea29d7efe25f85fa3db70b9c4335e86f4a88','source_pages':[109]],['clause_id':'FSAE-2027-V1:EV.8.7.1:p002','source_rule_id':'EV.8.7.1','source_sha256':'f71df5552e341dab1b58f1ff47212e7281953d66b9c41833de8347560913ed0e','source_text_sha256':'e0db1b480a72030a7b23414701c49244bfe581afe7f39ea774cc8c028acf727e','source_pages':[109]]],'classification':'technical_design_and_verification','interpretation_status':'interpreted_candidate','coverage_status':'prepared_not_applied','verification_method':'inspection_review_and_fault_injection','verification_status':'not_verified','evidence_status':'not_available','compliance_status':'not_claimed','conditions_json':'["Independent BSPD architecture and independence evidence still require design review."]','numeric_json':'[]','source_ids_json':'["FSAE-2027-V1:EV.8.7.1:p001","FSAE-2027-V1:EV.8.7.1:p002"]'],['id':'DD-12','title':'BSPD trip on persistent brake/high-power conflict or input fault','rules':['EV.8.7.2','EV.8.7.3'],'functions':['bspd-monitor','bspd-trip','tractive-current'],'owner':'shutdown independent BSPD / shutdown circuit interface','statement':'Open the shutdown circuit when hard braking coincides for longer than half a second with tractive current corresponding to five kilowatts delivered to motors at nominal battery voltage. Also open the shutdown circuit for any open or short on a BSPD sensor input. The symbolic current threshold is 5000 W divided by nominal battery voltage; the voltage, hard-braking criterion and actual circuit design remain unresolved. Global trip latching/manual-reset behavior belongs to the separate shutdown slice.','conditions':['Both hard braking and threshold-level tractive current for the persistence trip; any BSPD sensor input open/short for the fault trip.'],'numeric':[['quantity':'simultaneous condition persistence','value':0.5,'unit':'s','operator':'>'],['quantity':'power equivalent at nominal battery voltage','value':5,'unit':'kW','role':'current-threshold reference, not a measured-power comparator'],['quantity':'BSPD current threshold','expression':'5000 W / U_nominal','role':'derived relation; U_nominal unresolved']],'checks':'Review nominal-voltage threshold calculation and hard-braking input. Stimulate just below, at and above the current threshold and half-second boundary. Inject open/short faults on every input and demonstrate opening of the entire installed shutdown path.','source_refs':[['clause_id':'FSAE-2027-V1:EV.8.7.2:p001','source_rule_id':'EV.8.7.2','source_sha256':'f71df5552e341dab1b58f1ff47212e7281953d66b9c41833de8347560913ed0e','source_text_sha256':'b38d4f1d5069c6358b3051b59ed4e0f870ee69b73034e0650e466f5988fb47aa','source_pages':[109]],['clause_id':'FSAE-2027-V1:EV.8.7.2:p002','source_rule_id':'EV.8.7.2','source_sha256':'f71df5552e341dab1b58f1ff47212e7281953d66b9c41833de8347560913ed0e','source_text_sha256':'90bfec662832f5913b446f963af145cbab35dbb603d06d86911c71e38a1a9d4d','source_pages':[109]],['clause_id':'FSAE-2027-V1:EV.8.7.2:p003','source_rule_id':'EV.8.7.2','source_sha256':'f71df5552e341dab1b58f1ff47212e7281953d66b9c41833de8347560913ed0e','source_text_sha256':'70d2432accbb375fdeee15f52416fb32a9766e02844d3bc140cede341a30ebbf','source_pages':[109]],['clause_id':'FSAE-2027-V1:EV.8.7.3:p001','source_rule_id':'EV.8.7.3','source_sha256':'f71df5552e341dab1b58f1ff47212e7281953d66b9c41833de8347560913ed0e','source_text_sha256':'7dca908117ffb25cc8fc78dea3e1ae83b0fba1d776670464ed343f2cfb1466ed','source_pages':[109]]],'classification':'technical_design_and_verification','interpretation_status':'interpreted_candidate','coverage_status':'prepared_not_applied','verification_method':'inspection_review_and_fault_injection','verification_status':'not_verified','evidence_status':'not_available','compliance_status':'not_claimed','conditions_json':'["Both hard braking and threshold-level tractive current for the persistence trip; any BSPD sensor input open/short for the fault trip."]','numeric_json':'[{"quantity":"simultaneous condition persistence","value":0.5,"unit":"s","operator":">"},{"quantity":"power equivalent at nominal battery voltage","value":5,"unit":"kW","role":"current-threshold reference, not a measured-power comparator"},{"quantity":"BSPD current threshold","expression":"5000 W / U_nominal","role":"derived relation; U_nominal unresolved"}]','source_ids_json':'["FSAE-2027-V1:EV.8.7.2:p001","FSAE-2027-V1:EV.8.7.2:p002","FSAE-2027-V1:EV.8.7.2:p003","FSAE-2027-V1:EV.8.7.3:p001"]'],['id':'DD-13','title':'Demonstrate complete BSPD without energizing motors','rules':['EV.8.7.4'],'functions':['inspection','bspd-monitor','bspd-trip'],'owner':'technical inspection process / BSPD test interface','statement':'Demonstrate the complete installed BSPD including its current sensor without delivering power to vehicle motors. Use a separate wire and external supply to simulate tractive current while the brake pedal is pressed.','conditions':['Installed-vehicle test; isolated stimulus is not proof obtained by the model script.'],'numeric':[],'checks':'Prepare an approved safe inspection procedure, isolate motor power and record that no motor power is delivered. Apply external current through the separate stimulus wire while pressing the brake; verify current-sensor response and full BSPD shutdown operation.','source_refs':[['clause_id':'FSAE-2027-V1:EV.8.7.4:p001','source_rule_id':'EV.8.7.4','source_sha256':'f71df5552e341dab1b58f1ff47212e7281953d66b9c41833de8347560913ed0e','source_text_sha256':'0e73970ebb71cd69bb0586cb45352e248f7ebf44f62476b3be936553ac51743f','source_pages':[109]],['clause_id':'FSAE-2027-V1:EV.8.7.4:p002','source_rule_id':'EV.8.7.4','source_sha256':'f71df5552e341dab1b58f1ff47212e7281953d66b9c41833de8347560913ed0e','source_text_sha256':'93e949c9aa9102c69d3cb70dbf5be969fe87c1a39ca12c17776063abf7da98be','source_pages':[109]],['clause_id':'FSAE-2027-V1:EV.8.7.4:p003','source_rule_id':'EV.8.7.4','source_sha256':'f71df5552e341dab1b58f1ff47212e7281953d66b9c41833de8347560913ed0e','source_text_sha256':'7e4129504506f01342de8a4aeae55827b70a4e00e774174cd63fa4ef5a01cf9f','source_pages':[109]],['clause_id':'FSAE-2027-V1:EV.8.7.4:p004','source_rule_id':'EV.8.7.4','source_sha256':'f71d