        assert fn != null
        base[key].functions[layer] = fn
    }
    [logical:'Logical subsystem',behavior:'Physical behavior',equipment:'Equipment',ci:'Subsystem CI'].each { field, suffix ->
        def type = field == 'logical' ? 'LogicalComponent' : field == 'ci' ? 'ConfigurationItem' : 'PhysicalComponent'
