            ['APPS healthy','APPS failure pending','Detect APPS fault','APPS calibrated travel disagreement > 10%, or APPS sensor/wiring/range failure; start APPS timer independently of BSE timer.'],
            ['APPS failure pending','APPS healthy','Transient APPS fault clears','APPS failure disappears before persistence exceeds 100 ms; approved sampling and timing design UNRESOLVED.'],
            ['APPS failure pending','APPS failure inhibited','Persistent APPS fault','APPS failure persists > 100 ms: immediately and completely stop motor power (T.4.2.5). SDC need not open.'],
            ['APPS failure inhibited','APPS healthy','Approved APPS fault recovery','APPS validated healthy AND engineer-approved recovery/reset criterion. Source does not prescribe this criterion; unresolved conservative candidate.']]],
        [name:'BSE independent fault timing',states:['BSE healthy','BSE failure pending','BSE failure inhibited'],initial:'BSE failure inhibited',
            availability:['BSE healthy':['brake-fault'],'BSE failure pending':['brake-fault'],'BSE failure inhibited':['brake-fault']],transitions:[
            ['BSE healthy','BSE failure pending','Detect BSE fault','BSE sensor/wiring/range failure; start BSE timer independently of APPS timer.'],
            ['BSE failure pending','BSE healthy','Transient BSE fault clears','BSE failure disappears before persistence exceeds 100 ms; approved sampling and timing design UNRESOLVED.'],
            ['BSE failure pending','BSE failure inhibited','Persistent BSE fault','BSE failure persists > 100 ms: immediately and completely stop motor power (T.4.3.3). SDC need not open.'],
            ['BSE failure inhibited','BSE healthy','Approved BSE fault recovery','BSE validated healthy AND engineer-approved recovery/reset criterion. Source does not prescribe this criterion; unresolved conservative candidate.']]]
    ]
    ['Driver demand brake conflict state machine','Driver demand APPS fault state machine','Driver demand BSE fault state machine'].eachWithIndex { name,index ->
        machinesByOwner.guard << machine(components.guard.LA,name,[guardRegions[index]])
    }
    ['LA','PA'].each { layer ->
        machinesByOwner.bspd << machine(components.bspd[layer],'Nonprogrammable BSPD hardware state machine',[
            [name:'Independent BSPD hardware trip',states:['BSPD monitoring','BSPD trip requested'],initial:'BSPD monitoring',
                availability:['BSPD monitoring':['bspd-monitor'],'BSPD trip requested':['bspd-monitor','bspd-trip']],transitions:[
                ['BSPD monitoring','BSPD trip requested','Trip simultaneous hard brake and current','Hard braking AND TS current at threshold corresponding to 5 kW DC at nominal battery voltage persist together > 0.5 s: open SDC (EV.8.7.2). I_threshold = 5000 W / U_nominal; voltage and hard-braking threshold UNRESOLVED.'],
                ['BSPD monitoring','BSPD trip requested','Trip BSPD input open or short','Any BSPD sensor input open or short circuit: open SDC (EV.8.7.3). No programmable dependency.']]]
        ])
    }
    // Native realization traces preserve the modeled interface across perspective boundaries.
    def groupedExchanges = [:]
    api.findAll('FunctionalExchange').findAll { it.name?.startsWith(prefix) }.each { exchange ->
        def parts = exchange.name.substring(prefix.length()).split(' ',2)
        if (!groupedExchanges.containsKey(parts[1])) groupedExchanges[parts[1]] = [:]
        groupedExchanges[parts[1]][parts[0]] = exchange
        if (parts[0] != 'OA') {
            api.rename(exchange.source,prefix + parts[0] + ' ' + parts[1] + ' source')
            api.rename(exchange.target,prefix + parts[0] + ' ' + parts[1] + ' target')
        }
    }
    groupedExchanges.each { name,byLayer ->
        [['SA','OA'],['LA','SA'],['PA','LA']].each { pair ->
            def lower = byLayer[pair[0]], higher = byLayer[pair[1]]
            assert lower != null && higher != null
            def realization = org.polarsys.capella.core.data.fa.FaFactory.eINSTANCE.createFunctionalExchangeRealization()
            realization.sourceElement = lower; realization.targetElement = higher
            lower.ownedFunctionalExchangeRealizations.add(realization)
            if (pair[1] != 'OA') ['source','target'].each { field ->
                def portRealization = org.polarsys.capella.core.data.information.InformationFactory.eINSTANCE.createPortRealization()
                portRealization.sourceElement = lower[field]; portRealization.targetElement = higher[field]
                lower[field].ownedPortRealizations.add(portRealization)
            }
        }
    }
    def decision = constraint('decision unresolved calibration thresholds and recovery',
        'UNRESOLVED: APPS ranges and raw transfer calibration; BSE range and mechanical engagement; hard-braking threshold; nominal battery voltage and BSPD current threshold; sampling and timer tolerances; low-speed interval endpoints and invalid-speed behavior; approved sensor-fault recovery; inspection isolation and jack colour/location; hardware selection and ratings. BSPD no automatic reset: shutdown slice owns EV.8.2.2 manual latch recovery. Source examples 0.5/4.5 V are not mandatory universal thresholds.',api.layer('SA'))
    ['LA','PA'].each { layer ->
        constraint(layer + ' motor inhibit arbitration',
            'Candidate output contract: OR all qualified APPS fault, BSE fault, brake-conflict latch and independent shutdown inhibits; any active inhibit means zero power to every motor and zero commanded regenerative torque. No alternate command path may bypass this output gate. Otherwise accept only driver-bounded total wheel torque, forward-drive authorization and low-speed regeneration authorization. Powertrain design and measured output evidence remain UNRESOLVED and NOT VERIFIED.',functions['motor-inhibit'][layer])
    }
    def derivedModule = req.createModule(api.layer('SA'),'FSAE2027:DD:module','Driver demand and BSPD derived candidate obligations')
    def folder = req.createFolder(derivedModule,'FSAE2027:DD:derived','Driver demand and BSPD interpreted candidate obligations')
    obligations.each { obligation ->
        def derived = req.create(folder,'FSAE2027:DD:' + obligation.id,obligation.title,obligation.statement)
        def verification = constraint('verify ' + obligation.id + ' NOT VERIFIED',
            obligation.checks + ' Evidence: unavailable. Status: NOT VERIFIED. Conditions: ' + obligation.conditions.join(' ') + ' Source: ' + obligation.source_refs.collect { it.clause_id }.join(', '),api.layer('SA'))
        def owners = []
        obligation.functions.each { key ->
            layers.each { layer -> owners << functions[key][layer] }
            def spec = functionSpecs.find { it.key == key }
            owners.addAll(components[spec.owner].values())
            owners.addAll(hardwareByOwner[spec.owner] ?: [])
            owners.addAll(machinesByOwner[spec.owner] ?: [])
        }
        owners = owners.unique()
        [derived].each { item ->
            [interpretation_status:'interpreted',coverage_status:'allocated',coverage_slice:'driver-demand-v1',
                source_document_id:'FSAE-2027-V1',source_sha256:obligation.source_refs[0].source_sha256,
                source_clause_ids:obligation.source_ids_json,
                classification:obligation.classification,model_owner:obligation.owner,verification_method:obligation.verification_method,
                verification_status:'not_verified',evidence_status:'not_available',compliance_status:'not_claimed',
                interpreted_obligation:obligation.statement,conditions:obligation.conditions_json,
                numeric_facts:obligation.numeric_json,model_element_ids:jsonIds(owners),
                verification_element_ids:jsonIds([verification])].each { key,value -> req.setAttribute(item,key,value) }
            owners.each { req.satisfy(it,item) }; req.verify(item,verification)
        }
        obligation.source_refs.each { ref ->
            def source = sources[ref.clause_id]
            req.derive(derived,source)
            owners.each { req.satisfy(it,source) }; req.verify(source,verification)
            [interpretation_status:'interpreted',coverage_status:'allocated',coverage_slice:'driver-demand-v1',
                model_owner:obligation.owner,verification_method:obligation.verification_method,verification_status:'not_verified',
                evidence_status:'not_available',compliance_status:'not_claimed',interpreted_obligation:obligation.statement,
                model_element_ids:jsonIds(owners),
                verification_element_ids:jsonIds([verification])].each { key,value -> req.setAttribute(source,key,value) }
        }
        state.requirements << [id:api.id(derived),identifier:'FSAE2027:DD:' + obligation.id,source_clauses:obligation.source_refs.collect { it.clause_id },verification:api.id(verification)]
    }
    constraint('slice v1 APPLIED','Candidate structure added for exactly ' + sources.size() + ' source paragraphs. Interpretation/allocations are modeled; all physical verification remains NOT VERIFIED. No rulebook-wide compliance claim.',api.layer('SA'))
    log.info('Added driver-demand candidate functions, interfaces, native safety state machines, EPBS items and source-grounded native Requirements traces. Physical verification remains pending.')
}
return state
